{
  "name": "strataglyph",
  "version": "0.13.1",
  "description": "The Strataglyph runner: builds a specification as code with a coding agent on your own computer.",
  "type": "module",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/mctavishdynamics/strataglyph.git",
    "directory": "packages/runner"
  },
  "homepage": "https://github.com/mctavishdynamics/strataglyph/tree/main/packages/runner#readme",
  "keywords": ["strataglyph", "piton", "runner", "claude-code", "codex", "opencode"],
  "engines": {
    "node": ">=24"
  },
  "bin": {
    "strataglyph": "./dist/cli.js"
  },
  "files": [
    "dist/cli.js",
    "dist/THIRD-PARTY-LICENSES.txt",
    "README.md",
    "LICENSE"
  ],
  "exports": {
    ".": "./src/index.ts"
  },
  "scripts": {
    "typecheck": "tsc -p .",
    "dev": "node src/cli.ts",
    "build": "node scripts/build.ts",
    "check-pack": "node scripts/check-pack.ts",
    "prepack": "npm run build"
  },
  "devDependencies": {
    "@strataglyph/shared": "*",
    "esbuild": "^0.28.2"
  }
}
